import{_ as t,a}from"./chunks/image-20261116062042218.D9BasGho.js";import{_ as r,o as d,c as i,a2 as s}from"./chunks/framework.CmPiTyN0.js";const h=JSON.parse('{"title":"Modular Damage","description":"","frontmatter":{"title":"Modular Damage","outline":"deep"},"headers":[],"relativePath":"en/wiki/damage.md","filePath":"en/wiki/damage.md","lastUpdated":1794811249000}'),n={name:"en/wiki/damage.md"};function o(l,e,p,m,c,u){return d(),i("div",null,[...e[0]||(e[0]=[s('<p><a href="./../index.html">← Back to Wiki Home</a></p><h2 id="_7-modular-damage" tabindex="-1">7. Modular Damage <a class="header-anchor" href="#_7-modular-damage" aria-label="Permalink to &quot;7. Modular Damage&quot;">​</a></h2><p>RVP resolves damage by part and module; different parts have independent durability, damage multipliers, and failure effects.</p><table tabindex="0"><thead><tr><th>Part/module</th><th>Failure effect</th></tr></thead><tbody><tr><td>ERA</td><td>The hit block fails after being penetrated, loses its protection, and changes appearance</td></tr><tr><td>Engine</td><td>Severe damage greatly reduces power and halves top speed; complete destruction removes all power and mobility</td></tr><tr><td>Barrel</td><td>Severe damage may cause firing failures or a barrel burst; even successful shots lose accuracy. Complete destruction prevents firing. At stage-1 damage, missile-type weapons only succeed or fail; they do not cause a barrel burst</td></tr><tr><td>Traverse</td><td>Severe damage greatly reduces traverse speed; complete destruction prevents rotation</td></tr><tr><td>Fire control system (FCS)</td><td>Stabilizer fails, ballistic calculation and CCIP stop, thermal/night vision and EO search become unavailable; the crosshair remains but provides no valid ballistic solution</td></tr><tr><td>Radar</td><td>Destroyed radar cannot search or track targets</td></tr><tr><td>APS/jammer/DIRCM/countermeasure launcher</td><td>Destroyed equipment loses its function</td></tr><tr><td>Maintenance equipment</td><td>Destroyed maintenance equipment cannot perform quick repairs</td></tr></tbody></table><p>Damage calculation uses part OBBs and independent damage multipliers; explosion direction, impact angle, armor reduction parameters, distance, ammunition type, and ERA state all affect final damage.</p><p>The repair panel restores parts by priority; ERA and support-equipment repair orders can be set separately.</p><p><img src="'+t+'" alt="image-20261116061921646"></p><p><img src="'+a+'" alt="image-20261116062042218"></p><p><strong>Figures 7.1/7.2 Severely damaged tanks.</strong></p><hr>',10)])])}const _=r(n,[["render",o]]);export{h as __pageData,_ as default};
